/// Given a collection of integer sequences, return a new sequence containing
/// the first element from each inner sequence. Assumes every inner sequence is non-empty.
fn get_first_elements(lst: Vec<Vec<i32>>) -> Vec<i32> {
    lst.into_iter()
       .map(|inner| inner[0])
       .collect()
}

